package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.Map;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.sail.lmdb.evaluation.IndependentSparqlOracle.Arm;
import org.eclipse.rdf4j.sail.lmdb.evaluation.IndependentSparqlOracle.EvaluationResult;
import org.eclipse.rdf4j.sail.lmdb.evaluation.IndependentSparqlOracle.ResultOrder;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

/**
 * Native LATERAL differential coverage (M7): correlation matrices, empty right arms, LIMIT-in-right subqueries,
 * BIND-in-right using plan-added functions, and scope-visibility cases must agree between the native engine and the
 * generic {@code LateralQueryEvaluationStep}.
 */
@Timeout(value = 120, unit = TimeUnit.SECONDS)
public class LmdbNativeLateralDifferentialTest {

	private static final String EX = "http://example.com/";
	private static final String PREFIX = "PREFIX ex: <" + EX + ">\nPREFIX xsd: <http://www.w3.org/2001/XMLSchema#>\n";

	@TempDir
	File dataDir;

	private IndependentSparqlOracle oracle;

	@BeforeEach
	public void setUp() throws Exception {
		oracle = IndependentSparqlOracle.builder(dataDir.toPath())
				.load(conn -> {
					ValueFactory vf = conn.getValueFactory();
					IRI knows = vf.createIRI(EX, "knows");
					IRI name = vf.createIRI(EX, "name");
					IRI score = vf.createIRI(EX, "score");
					for (int i = 0; i < 6; i++) {
						IRI person = vf.createIRI(EX, "p" + i);
						conn.add(person, name, vf.createLiteral("person " + i));
						conn.add(person, score, vf.createLiteral(i * 10));
						for (int j = 0; j < 6; j++) {
							if ((i + j) % 3 == 0 && i != j) {
								conn.add(person, knows, vf.createIRI(EX, "p" + j));
							}
						}
					}
					// p5 knows nobody with a score above 100: the empty-right case
					IRI q = vf.createIRI(EX, "q");
					IRI r = vf.createIRI(EX, "r");
					conn.add(vf.createIRI(EX, "s1"), vf.createIRI(EX, "p"), vf.createIRI(EX, "o1"));
					conn.add(vf.createIRI(EX, "s1"), q, vf.createIRI(EX, "left1"));
					conn.add(vf.createIRI(EX, "left1"), r, vf.createIRI(EX, "r1"));
					conn.add(vf.createIRI(EX, "left1"), r, vf.createIRI(EX, "r1b"));
					conn.add(vf.createIRI(EX, "s2"), vf.createIRI(EX, "p"), vf.createIRI(EX, "o2"));
					conn.add(vf.createIRI(EX, "s2"), q, vf.createIRI(EX, "left2"));
					conn.add(vf.createIRI(EX, "left2"), r, vf.createIRI(EX, "r2"));
				})
				.build();
	}

	@AfterEach
	public void tearDown() {
		oracle.close();
	}

	private void assertSameRows(String query) {
		oracle.assertEquivalent(query, ResultOrder.UNORDERED);
	}

	private void assertSameRowsNonEmpty(String query) {
		Map<Arm, EvaluationResult> results = oracle.assertEquivalent(query, ResultOrder.UNORDERED);
		assertThat(results.get(Arm.MEMORY_STANDARD).rows())
				.as("standard MemoryStore oracle must produce rows:\n%s", query)
				.isNotEmpty();
	}

	@Test
	public void basicCorrelation() {
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?a ex:knows ?b . LATERAL { ?b ex:name ?n } }");
		assertSameRowsNonEmpty(PREFIX
				+ "SELECT * WHERE { ?a ex:score ?s . LATERAL { ?a ex:knows ?b . ?b ex:score ?t . FILTER(?t > ?s) } }");
	}

	@Test
	public void emptyRightArm() {
		assertSameRows(PREFIX + "SELECT * WHERE { ?a ex:name ?n . LATERAL { ?a ex:doesNotExist ?x } }");
	}

	@Test
	public void limitInRight() {
		// per-left-row LIMIT: the defining LATERAL use case; the inner sub-select is a nested scope
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?a ex:name ?n . "
				+ "LATERAL { SELECT ?a (MAX(?t) AS ?best) WHERE { ?a ex:knows ?b . ?b ex:score ?t } GROUP BY ?a } }");
		assertSameRows(PREFIX + "SELECT * WHERE { ?a ex:name ?n . "
				+ "LATERAL { SELECT ?a ?b WHERE { ?a ex:knows ?b } ORDER BY ?b LIMIT 2 } }");
	}

	@Test
	public void optionalSubselectLimitIsFreshPerLateralInput() {
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?s ex:p ?o . "
				+ "LATERAL { OPTIONAL { SELECT * { ?s ex:q ?label } LIMIT 1 } } }");
	}

	@Test
	public void unionSubselectLimitsAreFreshPerLateralInput() {
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?s ex:p ?o . LATERAL { "
				+ "{ SELECT * { ?s ex:q ?label } ORDER BY ?label LIMIT 1 } UNION "
				+ "{ SELECT * { ?s ex:missing ?alternative } ORDER BY ?alternative LIMIT 1 } } }");
	}

	@Test
	public void bindInRightUsingPlanFunctions() {
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?a ex:name ?n . "
				+ "LATERAL { ?a ex:score ?s . BIND(CONCAT(STR(?n), \"/\", STR(?s)) AS ?tag) } }");
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?a ex:name ?n . "
				+ "LATERAL { ?a ex:score ?s . BIND(xsd:double(?s) AS ?d) FILTER(?d >= 0) } }");
	}

	@Test
	public void nestedLaterals() {
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?a ex:knows ?b . "
				+ "LATERAL { ?b ex:knows ?c . LATERAL { ?c ex:name ?cn } } }");
	}

	@Test
	public void nestedLateralSubselectDoesNotSeeHiddenOuterBindings() {
		String query = PREFIX + "SELECT * WHERE {\n"
				+ "  ?s ex:p ?o\n"
				+ "  LATERAL {\n"
				+ "    ?s ex:q ?left\n"
				+ "    LATERAL {\n"
				+ "      SELECT ?r { ?s ex:q ?left . ?left ex:r ?r } ORDER BY ?r LIMIT 1\n"
				+ "    }\n"
				+ "  }\n"
				+ "}";
		try {
			assertSameRowsNonEmpty(query);
		} catch (AssertionError failure) {
			throw new AssertionError(failure.getMessage() + "\nNative plan:\n"
					+ oracle.explain(Arm.LMDB_PRODUCTION, query, Explanation.Level.Optimized).rendered(), failure);
		}
	}

	@Test
	public void scopeVisibilityOfInnerPrivateVariables() {
		// ?hidden inside the right arm's sub-select is invisible outside; a same-named outer variable must not
		// correlate with it
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?a ex:knows ?hidden . "
				+ "LATERAL { SELECT ?a (COUNT(*) AS ?cnt) WHERE { ?a ex:knows ?hidden } GROUP BY ?a } }");
	}

	@Test
	public void lateralUnderOptionalAndUnion() {
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { ?a ex:name ?n . "
				+ "OPTIONAL { ?a ex:knows ?b . LATERAL { ?b ex:score ?t . FILTER(?t > 20) } } }");
		assertSameRowsNonEmpty(PREFIX + "SELECT * WHERE { { ?a ex:knows ?b . LATERAL { ?b ex:name ?n } } "
				+ "UNION { ?a ex:name ?n } }");
	}

	@Test
	public void killSwitchRestoresIslandRoute() {
		String query = PREFIX + "SELECT * WHERE { ?a ex:knows ?b . LATERAL { ?b ex:name ?n } }";
		EvaluationResult withNative = oracle.evaluate(Arm.LMDB_PRODUCTION, query);
		String previous = System.getProperty("rdf4j.lmdb.nativeLateral.enabled");
		System.setProperty("rdf4j.lmdb.nativeLateral.enabled", "false");
		try {
			EvaluationResult withIsland = oracle.evaluate(Arm.LMDB_PRODUCTION, query);
			assertThat(withIsland.failure()).isNull();
			assertThat(withIsland.multiset()).isEqualTo(withNative.multiset());
		} finally {
			if (previous == null) {
				System.clearProperty("rdf4j.lmdb.nativeLateral.enabled");
			} else {
				System.setProperty("rdf4j.lmdb.nativeLateral.enabled", previous);
			}
		}
	}
}
